require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$eventId=(int)($_GET['event']??0);$status=(string)($_GET['status']??'');$sql="SELECT vo.order_number,vo.created_at,vo.voter_name,vo.voter_phone,f.full_name finalist,f.category,r.name region,vo.amount_snapshot,vo.base_points_snapshot,vo.bonus_points_snapshot,vo.total_points_snapshot,vo.payment_status,vo.payment_channel,vo.xendit_payment_id,vo.paid_at FROM vote_orders vo JOIN finalists f ON f.id=vo.finalist_id JOIN regions r ON r.id=f.region_id WHERE vo.event_id=?";$params=[$eventId];if($status){$sql.=' AND vo.payment_status=?';$params[]=$status;}$sql.=' ORDER BY vo.id DESC';$stmt=db()->prepare($sql);$stmt->execute($params);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="transaksi-evoting-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Nomor Transaksi','Tanggal','Pemilih','Telepon','Finalis','Kelompok','Asal','Nominal','Poin Dasar','Bonus','Total Poin','Status','Kanal','Payment ID','Dibayar']);foreach($stmt as $r){$r['voter_phone']=decrypt_value($r['voter_phone']);fputcsv($out,array_values($r));}fclose($out);exit;
